def verify(tools, answer):
    import json
    import re

    def safe_get(d, *keys, default=None):
        for k in keys:
            if isinstance(d, dict):
                d = d.get(k, default)
            else:
                return default
        return d

    try:
        # Extract payload if wrapped in submit_result format
        if isinstance(answer, dict) and 'submitted_data' in answer:
            answer = answer['submitted_data']
        elif isinstance(answer, dict) and 'status' in answer and 'message' in answer:
            answer = answer.get('submitted_data', answer)

        if not isinstance(answer, list):
            return {'passed': False, 'message': 'Answer is not a list', 'details': {}}

        # Check that all items have required keys and non-empty safety_warning
        for idx, item in enumerate(answer):
            if not isinstance(item, dict):
                return {'passed': False, 'message': f'Item {idx} is not a dict', 'details': {}}
            required = ['description', 'verification_method', 'acceptable_criteria', 'safety_warning']
            for key in required:
                if key not in item or item[key] is None or (isinstance(item[key], str) and item[key].strip() == ''):
                    return {'passed': False, 'message': f'Item {idx} missing or empty required key: {key}', 'details': {}}

        # Combine all text from all items for searching
        all_text_lower = ''
        for item in answer:
            for key in ['description', 'verification_method', 'acceptable_criteria', 'safety_warning', 'example', 'notes']:
                val = item.get(key, '')
                if isinstance(val, str):
                    all_text_lower += val.lower() + ' '

        # Helper to get text from tool output (list of sections or dicts)
        def get_tool_text(tool_output, keys_to_extract=None):
            result = tool_output.get('result', tool_output)
            if not isinstance(result, list):
                if isinstance(result, dict):
                    result = [result]
                else:
                    return ''
            texts = []
            for entry in result:
                if isinstance(entry, dict):
                    if keys_to_extract:
                        for k in keys_to_extract:
                            val = entry.get(k, '')
                            if isinstance(val, str):
                                texts.append(val.lower())
                            elif isinstance(val, list):
                                for b in val:
                                    if isinstance(b, str):
                                        texts.append(b.lower())
                    else:
                        # extract all string values
                        for v in entry.values():
                            if isinstance(v, str):
                                texts.append(v.lower())
                            elif isinstance(v, list):
                                for b in v:
                                    if isinstance(b, str):
                                        texts.append(b.lower())
            return ' '.join(texts)

        # ---- Tool verification 1: Use compile_post_repair_gas_range_checklist to get reference checklist ----
        try:
            ref = tools['compile_post_repair_gas_range_checklist'](include_safety=True, include_diagnostic=True, include_flame=True)
            # ref is a dict with keys like 'checklist_items', 'bullets', 'summary', 'title'
            ref_text = ''
            # Extract from checklist_items if present
            checklist = ref.get('checklist_items', [])
            if isinstance(checklist, list):
                for ci in checklist:
                    if isinstance(ci, dict):
                        for v in ci.values():
                            if isinstance(v, str):
                                ref_text += v.lower() + ' '
                            elif isinstance(v, list):
                                for b in v:
                                    if isinstance(b, str):
                                        ref_text += b.lower() + ' '
            # Also extract from bullets
            bullets = ref.get('bullets', [])
            if isinstance(bullets, list):
                for b in bullets:
                    if isinstance(b, str):
                        ref_text += b.lower() + ' '
            # Also from summary and title
            for key in ['summary', 'title', 'text']:
                val = ref.get(key, '')
                if isinstance(val, str):
                    ref_text += val.lower() + ' '

            # Check that each important phrase from reference appears in answer
            essential_phrases = ['soapy water', 'bubbles', 'gas leak', 'blue flame', 'yellow', 'orange',
                                 '350', '10 minutes', 'thermometer', 'air shutter', 'lp gas', '1-2 inches',
                                 'deviation', '25']
            missing_phrases = []
            for phrase in essential_phrases:
                if phrase not in ref_text:
                    continue  # phrase not in reference, so not required
                if phrase not in all_text_lower:
                    missing_phrases.append(phrase)
            if missing_phrases:
                return {'passed': False, 'message': f'Answer missing essential phrases: {missing_phrases}', 'details': {}}
        except Exception as e:
            return {'passed': False, 'message': f'Exception in compile_post_repair_gas_range_checklist: {str(e)}', 'details': {}}

        # ---- Tool verification 2: Check gas leak detection content exists in source ----
        try:
            gas_tool_out = tools['get_checking_for_gas_content'](text_contains='soapy water')
            gas_text = get_tool_text(gas_tool_out)
            if 'soapy water' not in gas_text or 'bubbles' not in gas_text:
                return {'passed': False, 'message': 'Tool data does not confirm soapy water gas leak detection', 'details': {}}
        except Exception as e:
            return {'passed': False, 'message': f'Exception in gas leak tool: {str(e)}', 'details': {}}

        # ---- Tool verification 3: Check proper flame content ----
        try:
            flame_tool_out = tools['get_proper_flame_content'](text_contains='blue')
            flame_text = get_tool_text(flame_tool_out, keys_to_extract=['heading', 'text', 'bullets'])
            # Check that answer contains flame-related phrases that appear in tool output
            flame_phrases = ['blue', 'yellow', 'orange', '1-2 inches', 'flame height']
            for phrase in flame_phrases:
                if phrase in flame_text and phrase not in all_text_lower:
                    return {'passed': False, 'message': f'Answer missing flame phrase "{phrase}" which exists in tool data', 'details': {}}
        except Exception as e:
            return {'passed': False, 'message': f'Exception in flame tool: {str(e)}', 'details': {}}

        # ---- Tool verification 4: Check oven temperature calibration ----
        try:
            oven_tool_out = tools['get_oven_temperature_calibration_content'](text_contains='350')
            oven_text = get_tool_text(oven_tool_out, keys_to_extract=['heading', 'text', 'bullets'])
            oven_phrases = ['350', '10 minutes', 'thermometer', 'deviation', '25']
            for phrase in oven_phrases:
                if phrase in oven_text and phrase not in all_text_lower:
                    return {'passed': False, 'message': f'Answer missing oven phrase "{phrase}" which exists in tool data', 'details': {}}
        except Exception as e:
            return {'passed': False, 'message': f'Exception in oven tool: {str(e)}', 'details': {}}

        # ---- Tool verification 5: Check LP gas air shutter adjustment ----
        try:
            lp_tool_out = tools['get_kenmore_natural_gas_content'](text_contains='air shutter')
            lp_text = get_tool_text(lp_tool_out)
            lp_phrases = ['air shutter', 'lp gas', 'adjustment']
            for phrase in lp_phrases:
                if phrase in lp_text and phrase not in all_text_lower:
                    return {'passed': False, 'message': f'Answer missing LP gas phrase "{phrase}" which exists in tool data', 'details': {}}
        except Exception as e:
            return {'passed': False, 'message': f'Exception in LP gas tool: {str(e)}', 'details': {}}

        # All checks passed
        return {'passed': True, 'message': 'All verification checks passed', 'details': {}}
    except Exception as e:
        return {'passed': False, 'message': f'Unexpected error: {str(e)}', 'details': {}}

